function replaceSection(txt, n, content) {
  const start = txt.search(new RegExp(`^## ${n}\\. `, 'm'));
  const end = txt.search(new RegExp(`^## ${n + 1}\\. `, 'm'));
  if (start < 0 || end < 0) throw new Error(`section ${n} absente`);
  const heading = txt.slice(start, txt.indexOf('\n', start));
  return `${txt.slice(0, start)}${heading}\n\n${content.trim()}\n\n${txt.slice(end)}`;
}
const catalog = JSON.parse(fs.readFileSync('specs/catalog.json', 'utf8'));
for (const [id, d] of Object.entries(details)) {
  const s = catalog.specs.find((x) => x.id === id);
  let txt = fs.readFileSync(s.path, 'utf8');
  const steps = d.steps.map((x, i) => `${i + 1}. ${x} Commit \`${i < 3 ? 'feat' : 'test'}(${id}): ${['définit les contrats', 'implémente les services', 'construit le parcours', 'vérifie les cas'][i]}\`.`).join('\n');
  txt = replaceSection(txt, 8, `${steps}\n5. Exécuter \`node tools/sdd/validate.mjs ${id}\`, renseigner les preuves réellement produites puis \`complete.mjs\`.`);
  txt = replaceSection(txt, 9, `- **Créés** : ${d.files.map((x) => `\`${x}\``).join(', ')}.\n- **Modifiés** : ${d.changed.map((x) => `\`${x}\``).join(', ')}.\n- **Lus / réutilisés** : ${s.dependsOn.map((x) => `\`${catalog.specs.find((y) => y.id === x)?.path}\``).join(', ')}.`);
  const nCa = [...txt.matchAll(/^- \*\*CA-(\d+)\*\*/gm)].length;
  const tests = [
    `**Unitaires** (${d.unit.length} fichiers, \`[${id}]\`) :`,
    ...d.unit.map((x) => `- ${x}`),
    '',
    `**Intégration** (Supabase local, \`LLM_MODE=mock\`, \`[${id}]\`) :`,
    ...d.integration.map((x) => `- ${x}`),
    '',
    `**End-to-end** (\`${d.files.find((x) => x.includes('/e2e/'))}\`, vidéo) :`,
    ...d.e2e.map((x) => `- **Scénario** — ${x}`),
    '',
    `**Visuel** — \`test('conformité ${id} @${id} @visual')\` : ${d.visual}`,
    '',
    `**Non-régression** — Rejouer ${s.dependsOn.map((x) => `\`[${x}]\` et \`@${x}\``).join(', ')} et les suites complètes unitaires/intégration.`,
    '',
    '| Critère | Tests |',
    '|---|---|',
    ...Array.from({ length: nCa }, (_, i) => `| CA-${i + 1} | ${i === nCa - 1 ? `\`@${id} @visual\`, axe, vidéo` : i === nCa - 2 ? 'intégration RLS/idempotence, e2e erreur' : `unitaires et intégration ciblés ; e2e \`@${id}\``} |`),
  ].join('\n');
  txt = replaceSection(txt, 12, tests);
  fs.writeFileSync(s.path, txt, 'utf8');
  console.log(id, txt.split(/\s+/).length);
}
